 NifModel model;VertexEditorTest::fixture(model);int first=MaterialPanel::createMaterial(&model,"FOOTING_01"),second=MaterialPanel::createMaterial(&model,"FOOTING_01");check(model.get<QString>(model.getBlock(second),"Name")=="FOOTING_02","material library creates unique numbered names");
