 check(model.get<QString>(model.getBlock(first),"Name")=="FOOTING_CUSTOM" && std::abs(model.get<float>(model.getBlock(first),"Alpha")-.5f)<.001f && model.get<float>(model.getBlock(first),"Glossiness")==32 && model.get<Color3>(model.getBlock(first),"Diffuse Color").toQColor()==QColor(64,128,192),"material editor applies name color opacity and glossiness");model.undo();check(bytes(model)==before,"material field editing undoes in one exact step");model.redo();QCoreApplication::processEvents();
