 int editedTexture=textureProperty(3);check(editedTexture!=originalTexture && textureProperty(1)==originalTexture,"texture editing detaches the selected mesh from shared descriptors");auto baseSource=model.getBlock(model.getLink(model.getIndex(model.getBlock(editedTexture),"Base Texture"),"Source"));check(model.get<QString>(baseSource,"File Name")=="textures/replacement.dds" && model.get<bool>(model.getBlock(editedTexture),"Has Glow Texture"),"texture editor replaces and adds map slots");
 check(model.get<QString>(model.getBlock(model.getLink(model.getIndex(model.getBlock(originalTexture),"Base Texture"),"Source")),"File Name")=="textures/footing.dds","texture editing preserves the original mesh source");auto textureBytes=bytes(model);NifModel textureReload;QBuffer textureInput(&textureBytes);textureInput.open(QIODevice::ReadOnly);check(textureReload.load(textureInput) && textureReload.get<QString>(textureReload.getBlock(textureReload.getLink(textureReload.getIndex(textureReload.getBlock(editedTexture),"Base Texture"),"Source")),"File Name")=="textures/replacement.dds","edited texture links and paths survive save/reload");model.undo();check(bytes(model)==before,"map edits undo in one exact step");model.redo();check(bytes(model)==textureBytes,"map edits redo exactly");QCoreApplication::processEvents();panel->findChild<QLineEdit *>("materialTexture4")->clear();panel->findChild<QPushButton *>("applyMaterial")->click();check(!model.get<bool>(model.getBlock(textureProperty(3)),"Has Glow Texture"),"clearing a map disables its slot");model.undo();QCoreApplication::processEvents();
 auto originalName=model.get<QString>(model.getBlock(first),"Name");panel->findChild<QPushButton *>("uniqueMaterial")->click();int independent=MaterialPanel::assignedMaterial(&model,model.getBlock(3));check(independent!=first && MaterialPanel::assignedMaterial(&model,model.getBlock(1))==first,"material inspector makes the assigned mesh independent");QCoreApplication::processEvents();panel->findChild<QLineEdit *>("materialName")->setText("INDEPENDENT");panel->findChild<QPushButton *>("applyMaterial")->click();check(model.get<QString>(model.getBlock(first),"Name")==originalName,"editing unique material preserves the original");panel->findChild<QPushButton *>("createMaterial")->click();int created=MaterialPanel::assignedMaterial(&model,model.getBlock(3));check(created>=0 && created!=independent && model.getChildLinks(3).contains(created),"New + Assign creates a material attached to the selected mesh");
 panel->grab().save(QCoreApplication::applicationDirPath()+"/material-editor-preview.png");delete panel;
 auto window=new NifSkope;auto document=window->findChild<NifModel *>();VertexEditorTest::fixture(*document);window->select(document->getBlock(1));window->findChild<QAction *>("aMaterialEditor")->trigger();auto dock=window->findChild<QDockWidget *>("MaterialEditorDock");check(dock && !dock->isHidden() && dock->findChild<MaterialPanel *>(),"Materials menu opens the docked material editor");dock->findChild<QPushButton *>("createMaterial")->click();check(MaterialPanel::assignedMaterial(document,document->getBlock(1))>=0,"material dock follows the selected mesh");auto freshPanel=dock->findChild<MaterialPanel *>();freshPanel->findChild<QLineEdit *>("materialTexture0")->setText("textures/new.dds");freshPanel->findChild<QPushButton *>("applyMaterial")->click();bool attached=false;for(int id:document->getLinkArray(document->getBlock(1),"Properties"))if(document->inherits(document->getBlock(id),"NiTexturingProperty"))attached=document->get<bool>(document->getBlock(id),"Has Base Texture") && document->getLink(document->getIndex(document->getBlock(id),"Base Texture"),"Source")>=0;check(attached,"adding the first texture creates and attaches its descriptor and source");delete window;
